    const releaseYear = details?.releaseDate && details.releaseDate !== "Keine Angabe"
      ? details.releaseDate.split("-")[0]
      : "";
    const titleWithYear = releaseYear ? `${cleanTitle} ${releaseYear}` : cleanTitle;

